// Loaded image HEADS original process, section catalogs/stumps plus separate boundary controls.
import org.audiveris.omr.sheet.Book;import java.util.*;import java.nio.file.*;import java.awt.Point;import java.awt.geom.*;
public class StemImageStumpsProbe extends StemPartsLookupProbe {
 private final Object book;public StemImageStumpsProbe(Book b,SortedSet<Integer> ids){super(b,ids);book=b;}
 static Object dynamic(int first,int[][]runs)throws Exception {Object s=Class.forName("org.audiveris.omr.lag.DynamicSection").getConstructor(Class.forName("org.audiveris.omr.run.Orientation")).newInstance(en("run.Orientation","VERTICAL"));call(s,"setFirstPos",first);for(int[]r:runs)call(s,"append",Class.forName("org.audiveris.omr.run.Run").getConstructor(int.class,int.class).newInstance(r[0],r[1]));return s;}
 static String sectionGlyph(Object s)throws Exception {if((Integer)call(s,"getWeight")==0)return "null";Object c=Class.forName("org.audiveris.omr.glyph.dynamic.SectionCompound").getConstructor().newInstance();call(c,"addSection",s);return physical(call(c,"toGlyph",(Object)null));}
 static String groups(Object g)throws Exception {List<String>x=new ArrayList<>();for(Object a:(Collection<?>)call(g,"getGroups"))x.add(a.toString());Collections.sort(x);List<String>y=new ArrayList<>();for(String a:x)y.add("\""+a+"\"");return "["+String.join(",",y)+"]";}
 public void process(){try{
 Object sheet=call(((List<?>)call(book,"getStubs")).get(0),"getSheet");List<String>systems=new ArrayList<>(),intersections=new ArrayList<>(),contains=new ArrayList<>(),crops=new ArrayList<>();Object firstCorner=null;int corners=0;
 for(Object sys:(List<?>)call(sheet,"getSystems")){
 Object retr=Class.forName("org.audiveris.omr.sheet.stem.StemsRetriever").getConstructor(Class.forName("org.audiveris.omr.sheet.SystemInfo")).newInstance(sys);call(retr,"process");Object p=get(retr,"params");List<String>sections=new ArrayList<>(),cases=new ArrayList<>();for(Object s:(Collection<?>)call(sys,"getVerticalSections"))sections.add(section(s));
 for(Object head:(List<?>)get(retr,"systemHeads")){Object hl=call(head,"getLinker");if(hl==null)continue;for(String side:new String[]{"LEFT","RIGHT"})for(String vert:new String[]{"TOP","BOTTOM"}){Object c=call(hl,"getCornerLinker",en("util.HorizontalSide",side),en("util.VerticalSide",vert));if(firstCorner==null)firstCorner=c;Object stump=call(c,"getStump");cases.add("{\"head_bounds\":"+rect(call(head,"getBounds"))+",\"shape\":\""+call(head,"getShape")+"\",\"side\":\""+side+"\",\"vertical\":\""+vert+"\",\"stump\":"+(stump==null?"null":physical(stump))+"}");corners++;}}
 systems.add("{\"system\":"+call(sys,"getId")+",\"main_stem_thickness\":"+get(p,"mainStemThickness")+",\"stump_area_dy\":"+get(p,"stumpAreaDy")+",\"stump_area_dx_in\":"+get(p,"stumpAreaDxIn")+",\"stump_area_dx_out\":"+get(p,"stumpAreaDxOut")+",\"sections\":["+String.join(",",sections)+"],\"cases\":["+String.join(",",cases)+"]}");
 }
 Object synthetic=dynamic(10,new int[][]{{20,3},{24,2},{22,2}});for(double[]box:new double[][]{{9,20,1,1},{9.5,20,1,1},{10,23,1,1},{11,24,1,1},{13,22,1,1},{12,24,1,1},{10,19,1,1},{10,22,1,1}}){Area a=new Area(new Rectangle2D.Double(box[0],box[1],box[2],box[3]));intersections.add("{\"first_pos\":10,\"runs\":[[20,3],[24,2],[22,2]],\"area\":"+Arrays.toString(box)+",\"intersects\":"+call(synthetic,"intersects",a)+"}");}for(int[]q:new int[][]{{10,20},{10,23},{11,23},{11,24},{12,22},{13,22}})contains.add("{\"first_pos\":10,\"runs\":[[20,3],[24,2],[22,2]],\"point\":"+Arrays.toString(q)+",\"contains\":"+call(synthetic,"contains",new Point(q[0],q[1]))+"}");
 Object old=get(firstCorner,"refPt");try{for(double x:new double[]{9,10,10.5,11.5,12.5,13.5,16}){set(firstCorner,"refPt",new Point2D.Double(x,22));Object sub=call(firstCorner,"getSubSection",synthetic);crops.add("{\"first_pos\":10,\"runs\":[[20,3],[24,2],[22,2]],\"reference_x\":"+x+",\"stem_thickness\":"+call(call(sheet,"getScale"),"getStemThickness")+",\"glyph\":"+sectionGlyph(sub)+"}");}}finally{set(firstCorner,"refPt",old);}
 Object index=call(sheet,"getGlyphIndex"),seed=glyph(2000,2500,2,3,"VERTICAL"),incoming=glyph(2000,2500,2,3,"VERTICAL");call(seed,"addGroup",en("glyph.GlyphGroup","VERTICAL_SEED"));Object saved=call(index,"registerOriginal",seed);call(incoming,"addGroup",en("glyph.GlyphGroup","STUMP"));Object reused=call(index,"registerOriginal",incoming);String reuse="{\"same_original_object\":"+(saved==reused)+",\"groups\":"+groups(reused)+"}";
 Object rejected=glyph(2010,2500,2,3,"VERTICAL");call(rejected,"addGroup",en("glyph.GlyphGroup","STUMP"));Object retained=call(index,"registerOriginal",rejected);String rejection="{\"stands_out\":"+call(firstCorner,"standsOut",retained)+",\"same_registered_entity\":"+(call(index,"getEntity",call(retained,"getId"))==retained)+",\"groups\":"+groups(retained)+"}";
 Files.writeString(Path.of(System.getProperty("native.probe.output")),"{\"native_outputs_used\":false,\"corners\":"+corners+",\"systems\":["+String.join(",",systems)+"],\"run_intersection_controls\":["+String.join(",",intersections)+"],\"polygon_contains_controls\":["+String.join(",",contains)+"],\"subsection_controls\":["+String.join(",",crops)+"],\"registry_reuse_control\":"+reuse+",\"registered_rejected_control\":"+rejection+"}");
 }catch(Exception e){throw new RuntimeException(e);}}
}
